/**
 * Lee el texto desde $input.first().json.Mensajes (puede venir con \n literales y entidades HTML)
 * Detecta "Notificación de Caso DevOps – Soporte de Operación"
 * y extrae en PascalCase:
 *   CasoId, TituloCaso, Cliente, BaseDeDatos, Operacion, UrlCaso, Query
 * También expone: esCasoDevOps, tieneQuery, errores, Sentencias, texto_normalizado.
 *
 * Soporta etiquetas de bloque:
 *   - "Query:"
 *   - "Consulta a ejecutar:"
 *   - "SQL Ejecutado:"
 *   - "SQL a ejecutar:"
 */

// ------- Utilidades -------
function decodeEntities(s) {
  return s.replace(/(&nbsp;|&lt;|&gt;|&amp;|&#39;|&quot;)/g, m => ({
    '&nbsp;': ' ',
    '&lt;': '<',
    '&gt;': '>',
    '&amp;': '&',
    '&#39;': "'",
    '&quot;': '"'
  })[m] || m);
}

function stripHtmlOnce(s) {
  return s
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<p[^>]*>/gi, '')
    .replace(/<[^>]*>/g, '');
}

function norm(s) {
  if (s == null) return '';
  if (Array.isArray(s)) s = s.join('\n\n');
  if (typeof s !== 'string') s = String(s);

  // Convertir literales "\n" a saltos reales si aplica
  if (/\\n/.test(s) && !/\n/.test(s)) s = s.replace(/\\n/g, '\n');

  // Normalización base
  s = s.replace(/\r\n?/g, '\n').replace(/[ \t]+\n/g, '\n');

  // 1) Quitar HTML bruto que ya venga como tags
  s = stripHtmlOnce(s).trim();

  // 2) Decodificar entidades (ej: &lt;/p&gt; -> </p>)
  s = decodeEntities(s);

  // 3) Quitar HTML que haya quedado tras decodificar
  s = stripHtmlOnce(s);

  // Limpieza final
  s = s.replace(/`{3,}[\w-]*/g, '') // quitar fences si vinieran
       .replace(/\u00A0/g, ' ')     // NBSP
       .replace(/\n{3,}/g, '\n\n')
       .trim();

  return s;
}

function pick(re, s, idx = 1) {
  const m = s.match(re);
  return m ? (m[idx] || '').trim() : '';
}

function extractUrl(line) {
  if (!line) return null;
  return (
    pick(/\((https?:\/\/[^\s)]+)\)/i, line) || // (URL) o [texto](URL)
    pick(/(https?:\/\/\S+)/i, line)
  ) || null;
}

// ------- Entrada -------
const entrada = $input.first().json.Mensajes;
const txt = norm(entrada);

// ------- Detección encabezado -------
const hasHeader = /Notificación\s+de\s+Caso\s+DevOps\s*[–—-]?\s*(?:Soporte\s+de\s+Operación)?/i.test(txt);

// ------- Extracciones (formato “Etiqueta: valor”) -------
const CasoId      = pick(/^\s*ID\s+del\s+Caso\s*:\s*([^\n]+)/im, txt) || null;
const TituloCaso  = pick(/^\s*T[íi]tulo\s+del\s+Caso\s*:\s*([^\n]+)/im, txt) || null;
const Cliente     = pick(/^\s*Cliente\s*:\s*([^\n]+)/im, txt) || null;
const BaseDeDatos = pick(/^\s*Base\s+de\s+Datos\s*:\s*([^\n]+)/im, txt) || null;
let   Operacion   = (pick(/^\s*Operaci[oó]n\s*:\s*([^\n]+)/im, txt) || '').toUpperCase() || null;

// URL de referencia
const urlLinea = pick(/^\s*URL\s+de\s+Referencia\s*:\s*([^\n]+)/im, txt) || null;
const UrlCaso  = extractUrl(urlLinea);

// ------- Bloque Query -------
// Acepta: "Query:", "Consulta a ejecutar:", "SQL Ejecutado:", "SQL a ejecutar:"
let Query = '';
{
  // Caso 1: etiqueta sola en su línea y el contenido debajo
  const labelBlockRe = /^(?:Query|Consulta(?:\s+a\s+ejecutar)?|SQL\s+Ejecutado|SQL\s+a\s+ejecutar)\s*:\s*$/im;
  const labelBlock = labelBlockRe.exec(txt);
  if (labelBlock) {
    const start = labelBlock.index + labelBlock[0].length;
    // Cortar en la siguiente etiqueta conocida o fin
    const stopRe = /^\s*(ID\s+del\s+Caso|T[íi]tulo\s+del\s+Caso|Cliente|Base\s+de\s+Datos|Operaci[oó]n|URL\s+de\s+Referencia)\s*:/im;
    const tail = txt.slice(start);
    const stop = stopRe.exec(tail);
    const endIdx = stop ? (start + stop.index) : txt.length;

    Query = txt.slice(start, endIdx)
      .replace(/```+[\w-]*/g, '')
      .replace(/^[ \t-]+/gm, '')
      .trim();
  }

  // Caso 2: etiqueta y contenido en la misma línea
  if (!Query) {
    Query = pick(/^(?:Query|Consulta(?:\s+a\s+ejecutar)?|SQL\s+Ejecutado|SQL\s+a\s+ejecutar)\s*:\s*([^\n][\s\S]*)$/im, txt) || '';
    if (Query) {
      const stopRe2 = /^\s*(ID\s+del\s+Caso|T[íi]tulo\s+del\s+Caso|Cliente|Base\s+de\s+Datos|Operaci[oó]n|URL\s+de\s+Referencia)\s*:/im;
      const m = stopRe2.exec(Query);
      if (m) Query = Query.slice(0, m.index).trim();
    }
  }
}

// Limpieza final del Query (por si quedaron entidades/tags sueltos)
Query = decodeEntities(Query)
  .replace(/<\/?[^>]+>/g, '')
  .trim();

// -------- Sentencias (útil para logs o validaciones) --------
const Sentencias = Query
  ? Query.split(/\n+|;\s*(?=\S)/).map(s => s.trim()).filter(Boolean)
  : [];

// -------- Validaciones --------
let errores = [];
if (!hasHeader)  errores.push('Falta encabezado "Notificación de Caso DevOps – Soporte de Operación".');
if (!CasoId)     errores.push('No se pudo extraer CasoId.');
if (!TituloCaso) errores.push('No se pudo extraer TituloCaso.');
if (!Query)      errores.push('No se pudo extraer Query.');

const tieneQuery   = !!Query;
// esCasoDevOps: detecta el caso aunque falte Query (header + ID)
const esCasoDevOps = hasHeader && !!CasoId;

// -------- Salida --------
return [
  {
    json: {
      esCasoDevOps,
      tieneQuery,
      errores,
      CasoId,
      TituloCaso,
      Cliente,
      BaseDeDatos,
      Operacion,
      UrlCaso,
      Query,
      Sentencias,
      texto_normalizado: txt
    }
  }
];

